//! `wj clean --generated`: remove the project's emitted `gen/` and `build/` directories.
//!
//! They are regenerated by `wj build`, and a stale copy misleads people and tools. A directory that holds a file git
//! tracks is never removed: its `gen/` or `build/` name does not make it output. A dry run unless `--yes` is given.

use anyhow::Result;
use std::path::{Path, PathBuf};

/// The directories this command may remove, named relative to the project root.
const OUTPUT_DIRS: [&str; 2] = ["gen", "build"];

/// Why a directory is kept, `None` when it is untracked output that can go.
fn tracked_files(root: &Path, dir: &Path) -> usize {
    let out = std::process::Command::new("git").arg("-C").arg(root).args(["ls-files", "-z", "--"]).arg(dir).stderr(std::process::Stdio::null()).output();
    match out {
        Ok(o) if o.status.success() => o.stdout.split(|b| *b == 0).filter(|s| !s.is_empty()).count(),
        _ => 0,
    }
}

fn size(dir: &Path) -> u64 {
    let Ok(rd) = std::fs::read_dir(dir) else { return 0 };
    rd.flatten().map(|e| if e.path().is_dir() { size(&e.path()) } else { e.metadata().map(|m| m.len()).unwrap_or(0) }).sum()
}

/// The project root for `start`: the directory of the nearest `wj.toml`, else `start`.
fn project_root(start: &Path) -> PathBuf {
    crate::module_system::project::find_manifest_dir(start).unwrap_or_else(|| start.to_path_buf())
}

pub fn run(start: &Path, yes: bool) -> Result<()> {
    let root = project_root(start);
    let mut removed = 0usize;
    let mut found = 0usize;
    for name in OUTPUT_DIRS {
        let dir = root.join(name);
        if !dir.is_dir() {
            continue;
        }
        found += 1;
        let tracked = tracked_files(&root, &dir);
        if tracked > 0 {
            println!("  kept {name}/ ({tracked} tracked file(s): not generated output)");
            continue;
        }
        let bytes = size(&dir);
        if yes {
            std::fs::remove_dir_all(&dir)?;
            println!("  removed {name}/ ({} KiB)", bytes / 1024);
            removed += 1;
        } else {
            println!("  would remove {name}/ ({} KiB)", bytes / 1024);
        }
    }
    if found == 0 {
        println!("  no gen/ or build/ directory in {}", root.display());
    } else if !yes {
        println!("  dry run: pass --yes to remove");
    } else {
        println!("  removed {removed} generated director{}", if removed == 1 { "y" } else { "ies" });
    }
    Ok(())
}
